local function hasValue(array, value)
    for i = 1, #array do
        if array[i] == value then
            return i
        end
    end
    return nil
end


-- Returns all the appearances for the given slot/subclass.
-- FILTRADO: solo devuelve apariencias que tengan al menos un item_template_id desbloqueado
-- (según ns.UnlockedAppearances, rellenado por PowerShell o Eluna).
function ns.GetSubclassAppearances(slot, subclass)
    assert(type(slot) == "string", "'slot' is mandatroy and must be 'string'.")
    assert(type(subclass) == "string", "'subclass' is mandatroy and must be 'string'.")
    local slotData = itemsData[slot] == nil and itemsData["Armor"][slot] or itemsData[slot]
    local raw = slotData and slotData[subclass]
    if not raw then
        return nil
    end

    -- Si no hay datos de desbloqueados, devolver todo (fallback)
    if not ns.IsAnyIdUnlocked or not next(ns.UnlockedAppearances or {}) then
        return raw
    end

    local filtered = {}
    for _, data in pairs(raw) do
        local ids = data[1]
        if ns.IsAnyIdUnlocked(ids) then
            table.insert(filtered, data)
        end
    end
    return filtered
end




-- Counts unlocked vs total appearance groups for a slot/subclass.
-- Returns unlockedCount, totalCount
function ns.GetSubclassAppearanceCounts(slot, subclass)
    assert(type(slot) == "string", "'slot' is mandatroy and must be 'string'.")
    assert(type(subclass) == "string", "'subclass' is mandatroy and must be 'string'.")
    local slotData = itemsData[slot] == nil and itemsData["Armor"][slot] or itemsData[slot]
    local raw = slotData and slotData[subclass]
    if not raw then
        return 0, 0
    end
    local total = 0
    local unlocked = 0
    local hasUnlockData = ns.IsAnyIdUnlocked and next(ns.UnlockedAppearances or {})
    for _, data in pairs(raw) do
        total = total + 1
        if not hasUnlockData then
            unlocked = unlocked + 1
        else
            local ids = data[1]
            if ns.IsAnyIdUnlocked(ids) then
                unlocked = unlocked + 1
            end
        end
    end
    return unlocked, total
end


-- Returns a table {[itemId] = "itemName",} of other items with the same appearance
-- (display id) as the item with the given id including the given id.
-- 'subclass' can be nil. Also returns 'subclass' as second value if nil.
function ns.GetOtherAppearances(itemId, slot, subclass)
    assert(type(itemId) == "number", "'itemId' is mandatroy and must be integer.")
    assert(type(slot) == "string", "'slot' is mandatroy and must be 'string'.")
    assert(subclass == nil or type(subclass) == "string", "'subclass' must be 'string' or 'nil'.")
    local slotData = itemsData[slot] == nil and itemsData["Armor"][slot] or itemsData[slot]
    if subclass ~= nil then
        local subclassData = slotData[subclass]
        for _, data in pairs(subclassData) do
            local ids = data[1]
            local names = data[2]
            local index = hasValue(ids, itemId)
            if index ~= nil then
                return ids, names, index, subclass
            end
        end
    else
        for subclass, subclassData in pairs(slotData) do
            for _, data in pairs(subclassData) do
                local ids = data[1]
                local names = data[2]
                local index = hasValue(ids, itemId)
                if index ~= nil then
                    return ids, names, index, subclass
                end
            end
        end
    end
end


